USE college_feedback_system;

CREATE TABLE IF NOT EXISTS feedback_dropdown_options (
  id INT AUTO_INCREMENT PRIMARY KEY,
  portal ENUM('student', 'staff') NOT NULL,
  option_group VARCHAR(40) NOT NULL,
  option_value VARCHAR(120) NOT NULL,
  option_label VARCHAR(120) NOT NULL,
  parent_value VARCHAR(120) NULL,
  sort_order INT NOT NULL,
  UNIQUE KEY uq_feedback_dropdown_option (portal, option_group, option_value, parent_value),
  INDEX idx_feedback_dropdown_lookup (portal, option_group, parent_value, sort_order)
) ENGINE=InnoDB;

